# Parse tree vs AST for "(1 + 2) * 3"
import re

tokens = re.findall(r"\d+|[()+*]", "(1 + 2) * 3")

# Concrete parse tree: every grammar rule and every token, parentheses included
def parse_tree(toks):
    pos = [0]
    def tk(): return toks[pos[0]] if pos[0] < len(toks) else None
    def eat(): pos[0] += 1; return toks[pos[0] - 1]
    def expr():
        kids = [term()]
        while tk() == "+": kids += [eat(), term()]
        return ("expr", kids)
    def term():
        kids = [factor()]
        while tk() == "*": kids += [eat(), factor()]
        return ("term", kids)
    def factor():
        if tk() == "(": return ("factor", [eat(), expr(), eat()])
        return ("factor", [eat()])
    return expr()

# AST: keep only meaning; grouping is the shape of the tree
def to_ast(node):
    kind, kids = node
    if isinstance(kids[0], str) and kids[0] == "(":
        return to_ast(kids[1])
    if kind == "factor":
        return int(kids[0])
    items = [to_ast(k) if isinstance(k, tuple) else k for k in kids]
    tree = items[0]
    for i in range(1, len(items), 2):
        tree = (items[i], tree, items[i + 1])
    return tree

def show(n, d=0):
    if isinstance(n, tuple) and isinstance(n[1], list):
        print("  " * d + n[0])
        for k in n[1]: show(k, d + 1)
    else:
        print("  " * d + str(n))

def count(n):
    return 1 + sum(count(k) for k in n[1]) if isinstance(n, tuple) and isinstance(n[1], list) else 1

pt = parse_tree(tokens)
print("tokens:", tokens)
print("parse tree nodes:", count(pt))
show(pt)
ast = to_ast(pt)
print("AST:", ast)   # ('*', ('+', 1, 2), 3): no parenthesis nodes

