public class Main {
    // Grammar: expr -> term (('+'|'-') term)* ; term -> factor (('*'|'/') factor)*
    //          factor -> NUMBER | '(' expr ')' | '-' factor
    static String s;
    static int pos;

    static char peek() { return pos < s.length() ? s.charAt(pos) : '\0'; }

    static int expr() {
        int v = term();
        while (peek() == '+' || peek() == '-') {      // loop = left associative
            char op = s.charAt(pos++);
            int r = term();
            v = op == '+' ? v + r : v - r;
        }
        return v;
    }

    static int term() {
        int v = factor();
        while (peek() == '*' || peek() == '/') {
            char op = s.charAt(pos++);
            int r = factor();
            if (op == '*') v *= r;
            else {
                if (r == 0) throw new ArithmeticException("division by zero");
                v /= r;                                // truncates toward zero
            }
        }
        return v;
    }

    static int factor() {
        char c = peek();
        if (c == '-') { pos++; return -factor(); }     // unary minus
        if (c == '(') {
            pos++;
            int v = expr();
            pos++;                                     // skip ')'
            return v;
        }
        int start = pos;
        while (Character.isDigit(peek())) pos++;
        return Integer.parseInt(s.substring(start, pos));
    }

    // Time O(n), space O(depth of nesting)
    public static void main(String[] args) {
        String[] tests = {"1+2*3", "(1+2)*3", "10-4-3", "-(2+3)*4", "7/2", "-7/2", "4/(2-2)"};
        for (String t : tests) {
            s = t; pos = 0;
            try { System.out.println(t + " = " + expr()); }
            catch (ArithmeticException e) { System.out.println(t + " = error: " + e.getMessage()); }
        }
    }
}

