#          factor -> NUMBER | '(' expr ')' | '-' factor
s = ""
pos = 0

def peek():
    return s[pos] if pos < len(s) else "\0"

def expr():
    global pos
    v = term()
    while peek() in "+-":            # loop = left associative
        op = s[pos]; pos += 1
        r = term()
        v = v + r if op == "+" else v - r
    return v

def term():
    global pos
    v = factor()
    while peek() in "*/":
        op = s[pos]; pos += 1
        r = factor()
        if op == "*":
            v *= r
        else:
            if r == 0:
                raise ZeroDivisionError("division by zero")
            q = abs(v) // abs(r)     # truncate toward zero like Java/C
            v = q if (v < 0) == (r < 0) else -q
    return v

def factor():
    global pos
    c = peek()
    if c == "-":                     # unary minus
        pos += 1
        return -factor()
    if c == "(":
        pos += 1
        v = expr()
        pos += 1                     # skip ')'
        return v
    start = pos
    while peek().isdigit():
        pos += 1
    return int(s[start:pos])

# Time O(n), space O(depth of nesting)
for t in ["1+2*3", "(1+2)*3", "10-4-3", "-(2+3)*4", "7/2", "-7/2", "4/(2-2)"]:
    s, pos = t, 0
    try:
        print(t, "=", expr())
    except ZeroDivisionError as e:
        print(t, "= error:", e)

