// Grammar: expr -> term (('+'|'-') term)* ; term -> factor (('*'|'/') factor)*
//          factor -> NUMBER | '(' expr ')' | '-' factor
let s = "";
let pos = 0;

function peek() { return pos < s.length ? s[pos] : "\0"; }

function expr() {
  let v = term();
  while (peek() === "+" || peek() === "-") {   // loop = left associative
    const op = s[pos++];
    const r = term();
    v = op === "+" ? v + r : v - r;
  }
  return v;
}

function term() {
  let v = factor();
  while (peek() === "*" || peek() === "/") {
    const op = s[pos++];
    const r = factor();
    if (op === "*") v *= r;
    else {
      if (r === 0) throw new Error("division by zero");
      v = Math.trunc(v / r);                   // truncate toward zero
    }
  }
  return v;
}

function factor() {
  const c = peek();
  if (c === "-") { pos++; return -factor(); }  // unary minus
  if (c === "(") {
    pos++;
    const v = expr();
    pos++;                                     // skip ')'
    return v;
  }
  const start = pos;
  while (peek() >= "0" && peek() <= "9") pos++;
  return parseInt(s.slice(start, pos), 10);
}

// Time O(n), space O(depth of nesting)
for (const t of ["1+2*3", "(1+2)*3", "10-4-3", "-(2+3)*4", "7/2", "-7/2", "4/(2-2)"]) {
  s = t; pos = 0;
  try { console.log(t + " = " + expr()); }
  catch (e) { console.log(t + " = error: " + e.message); }
}

