using System;

class Program
{
    // Grammar: expr -> term (('+'|'-') term)* ; term -> factor (('*'|'/') factor)*
    //          factor -> NUMBER | '(' expr ')' | '-' factor
    static string s;
    static int pos;

    static char Peek() { return pos < s.Length ? s[pos] : '\0'; }

    static int Expr()
    {
        int v = Term();
        while (Peek() == '+' || Peek() == '-')       // loop = left associative
        {
            char op = s[pos++];
            int r = Term();
            v = op == '+' ? v + r : v - r;
        }
        return v;
    }

    static int Term()
    {
        int v = Factor();
        while (Peek() == '*' || Peek() == '/')
        {
            char op = s[pos++];
            int r = Factor();
            if (op == '*') v *= r;
            else
            {
                if (r == 0) throw new DivideByZeroException("division by zero");
                v /= r;                              // truncates toward zero
            }
        }
        return v;
    }

    static int Factor()
    {
        char c = Peek();
        if (c == '-') { pos++; return -Factor(); }   // unary minus
        if (c == '(')
        {
            pos++;
            int v = Expr();
            pos++;                                   // skip ')'
            return v;
        }
        int start = pos;
        while (char.IsDigit(Peek())) pos++;
        return int.Parse(s.Substring(start, pos - start));
    }

    // Time O(n), space O(depth of nesting)
    static void Main()
    {
        string[] tests = { "1+2*3", "(1+2)*3", "10-4-3", "-(2+3)*4", "7/2", "-7/2", "4/(2-2)" };
        foreach (string t in tests)
        {
            s = t; pos = 0;
            try { Console.WriteLine(t + " = " + Expr()); }
            catch (DivideByZeroException e) { Console.WriteLine(t + " = error: " + e.Message); }
        }
    }
}
